import{_ as d,C as r,o as s,c as o,a5 as e,E as n}from"./chunks/framework.D_J2JZBr.js";const b=JSON.parse('{"title":"商用 EDA 工具链","description":"对照数字与模拟设计环节认识商用工具，并连接上科大 EE113L 和 Cadence 实训的往届流程。","frontmatter":{"title":"商用 EDA 工具链","description":"对照数字与模拟设计环节认识商用工具，并连接上科大 EE113L 和 Cadence 实训的往届流程。"},"headers":[],"relativePath":"tools/eda/commercial.md","filePath":"tools/eda/commercial.md","lastUpdated":1795531638000}'),i={name:"tools/eda/commercial.md"};function h(l,t,c,p,u,m){const a=r("CourseTable");return s(),o("div",null,[t[0]||(t[0]=e('<h1 id="商用-eda-工具链" tabindex="-1">商用 EDA 工具链 <a class="header-anchor" href="#商用-eda-工具链" aria-label="Permalink to &quot;商用 EDA 工具链&quot;">​</a></h1><p>商用工具首先按任务理解，再记产品名。同一环节的工具通常有相似目标，但脚本、数据库、许可功能和工艺认证不一定兼容。下表是常见对应，不是采购推荐，也不表示上科大当前提供全部授权；产品及版本以厂商、平台和课程公告为准。</p><h2 id="数字设计、验证与实现" tabindex="-1">数字设计、验证与实现 <a class="header-anchor" href="#数字设计、验证与实现" aria-label="Permalink to &quot;数字设计、验证与实现&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>常见工具</th><th>主要工作与应读的结果</th></tr></thead><tbody><tr><td>RTL / 门级仿真</td><td>Synopsys VCS、Cadence Xcelium、Siemens Questa</td><td>编译设计与测试平台、执行激励；检查日志、断言、覆盖和输出</td></tr><tr><td>波形与设计调试</td><td>Synopsys Verdi</td><td>连接波形、源码与层次；调试器通常需配合仿真器及相应数据库</td></tr><tr><td>静态规则检查与跨时钟域检查</td><td>Synopsys SpyGlass Lint / CDC</td><td>检查结构、编码与 CDC 问题；结论依赖时钟、复位和豁免设置</td></tr><tr><td>逻辑综合</td><td>Synopsys Design Compiler（DC）、Cadence Genus</td><td>把 RTL 映射到库单元；检查网表、时序、面积和未满足约束</td></tr><tr><td>可测性设计（DFT）</td><td>Synopsys TestMAX、Cadence Modus、Siemens Tessent</td><td>扫描、测试结构及测试生成等；具体能力取决于产品和授权模块</td></tr><tr><td>布局布线（P&amp;R）</td><td>Synopsys IC Compiler II（ICC2）、Cadence Innovus</td><td>布图规划、放置、时钟树、布线与优化；关注拥塞、时序和物理合法性</td></tr><tr><td>静态时序分析（STA）</td><td>Synopsys PrimeTime、Cadence Tempus</td><td>在指定工艺角与约束下检查建立、保持等时序要求</td></tr><tr><td>寄生参数提取</td><td>Synopsys StarRC、Cadence Quantus</td><td>根据布局布线和提取规则生成寄生电阻、电容等数据</td></tr><tr><td>物理验证</td><td>Siemens Calibre、Cadence Pegasus、Synopsys IC Validator</td><td>设计规则检查与版图网表一致性检查等；依赖匹配的规则文件</td></tr><tr><td>功耗与电源完整性</td><td>Synopsys PrimePower、Cadence Voltus</td><td>功耗分析；Voltus 也用于电压降、电迁移等分析，不能把不同检查等同起来</td></tr></tbody></table><p>物理验证常见缩写包括设计规则检查（Design Rule Checking，DRC）和版图与原理图一致性检查（Layout Versus Schematic，LVS）。时序、功耗和物理验证需要不同输入，不能因为某个环节没有报错，就认为其他环节自动通过。</p><h2 id="模拟与定制电路" tabindex="-1">模拟与定制电路 <a class="header-anchor" href="#模拟与定制电路" aria-label="Permalink to &quot;模拟与定制电路&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>常见工具</th><th>主要工作与边界</th></tr></thead><tbody><tr><td>原理图与定制版图</td><td>Cadence Virtuoso</td><td>管理器件、原理图、版图和设计数据库；并非仿真求解器本身</td></tr><tr><td>电路仿真</td><td>Cadence Spectre、Synopsys HSPICE</td><td>直流、交流、瞬态、噪声等电路分析；模型、分析设置与收敛都要检查</td></tr><tr><td>定制版图验证与提取</td><td>Calibre 等配套工具</td><td>DRC、LVS、寄生提取及后仿真；具体流程依课程 PDK 与授权配置</td></tr></tbody></table><p>模拟和数字工具并非完全割裂。数字标准单元也需要晶体管级设计、仿真与版图验证；大规模数字芯片则主要使用标准单元自动实现，不能把手工版图方法直接等同于整个芯片的后端流程。</p><h2 id="在上科大课程中怎样遇到这些工具" tabindex="-1">在上科大课程中怎样遇到这些工具 <a class="header-anchor" href="#在上科大课程中怎样遇到这些工具" aria-label="Permalink to &quot;在上科大课程中怎样遇到这些工具&quot;">​</a></h2>',9)),n(a,{codes:"EE113L,EE291F"}),t[1]||(t[1]=e('<h3 id="ee113l-从原理图到版图后仿真" tabindex="-1">EE113L：从原理图到版图后仿真 <a class="header-anchor" href="#ee113l-从原理图到版图后仿真" aria-label="Permalink to &quot;EE113L：从原理图到版图后仿真&quot;">​</a></h3><p>往届 EE113L Lab0 笔记记录的核心工具是 <strong>Virtuoso + Spectre / HSPICE + Calibre</strong>。实验路线包含反相器与复杂逻辑门的设计、版图、DRC / LVS、寄生提取和后仿真。因此，即使课程名是“数字集成电路 I 实验”，也需要理解定制电路和晶体管级方法。</p><p>这一工具记录来自往届材料，<strong>资料未注明统一学期版本</strong>，不代表今后实验必然使用同一组合。具体账号、环境、PDK、版本与提交方式，以当学期 <a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee113">EE113 / EE113L</a> 通知为准。</p><h3 id="cadence-暑期实训-数字实现与签核" tabindex="-1">Cadence 暑期实训：数字实现与签核 <a class="header-anchor" href="#cadence-暑期实训-数字实现与签核" aria-label="Permalink to &quot;Cadence 暑期实训：数字实现与签核&quot;">​</a></h3><p>维护者的 <strong>2026 年暑期实训版本</strong>笔记记录了以下对应：</p><table tabindex="0"><thead><tr><th>流程</th><th>工具</th><th>学习时重点</th></tr></thead><tbody><tr><td>逻辑综合</td><td>Genus</td><td>RTL、库、约束与综合报告</td></tr><tr><td>布图规划、布局、时钟树、布线</td><td>Innovus</td><td>物理约束、拥塞与时序优化</td></tr><tr><td>寄生提取</td><td>Quantus</td><td>提取数据与后续分析输入</td></tr><tr><td>时序签核分析</td><td>Tempus</td><td>工艺角、时序路径与约束</td></tr><tr><td>物理签核检查</td><td>Pegasus</td><td>规则文件与违规定位</td></tr><tr><td>功耗 / 电源完整性分析</td><td>Voltus</td><td>分析场景、活动率与电源网络</td></tr></tbody></table><p>这不是对每一届实训内容或签核深度的承诺。学习建议与课程介绍见 <a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/cadence-summer">Cadence 暑期实训</a>，环境操作见 <a href="/shanghaitech-ic-wiki-dev.github.io/tools/development/">EDA 环境</a>。</p><h2 id="不要只保存最后一张截图" tabindex="-1">不要只保存最后一张截图 <a class="header-anchor" href="#不要只保存最后一张截图" aria-label="Permalink to &quot;不要只保存最后一张截图&quot;">​</a></h2><p>一次实验至少记录工具版本、工艺库和角、脚本、约束、输入版本、日志和结果报告。遇到工具报错，先定位最早的有效错误，区分许可证失败、缺文件、语法错误和设计不满足规格，不要把所有问题都当作“软件没装好”。生成数据库成功也不意味着目标频率、功耗或验证条件已满足。</p><p>PDK、标准单元库、许可证配置和课程受限材料不得公开上传；需要分享时先确认授权范围，只提供允许公开的最小问题描述。</p><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">上科大信息学院 2026–2027 学年开课计划</a>。</li><li>本地往届资料：EE113L Lab0《Introduction to IC Design &amp; EDA Flow》与 2026 年《Cadence 集成电路暑期实训》笔记；仅提炼工具与流程，不公开环境凭证。</li><li>厂商官方主页：<a href="https://www.cadence.com/" target="_blank" rel="noreferrer">Cadence</a>、<a href="https://www.synopsys.com/" target="_blank" rel="noreferrer">Synopsys</a>、<a href="https://eda.sw.siemens.com/" target="_blank" rel="noreferrer">Siemens EDA</a>。</li></ul>',12))])}const _=d(i,[["render",h]]);export{b as __pageData,_ as default};
